const rows = $input.all();
const cfg = {};
for (const it of rows) {
  const k = it.json.setting !== undefined ? it.json.setting : it.json.key;
  if (k === undefined || k === null || String(k).trim() === '') continue;
  cfg[String(k).trim()] = it.json.value;
}
cfg.OWNER_NAME = 'Aditya';
cfg.SENDER_NAME = 'Aditya';
return [{ json: cfg }];

const cfg = $('Build CONFIG object').first().json;
const OWNER = cfg.OWNER_NAME;
const VALID_OWNERS = ['Aditya', 'Chaman', 'Akansha'];
const tz = cfg.TIMEZONE || 'Asia/Kolkata';
const nowTz = DateTime.now().setZone(tz);
const today = nowTz.toISODate();
const todayWeekday = nowTz.toFormat('cccc');
const rotateBySendDay = String(cfg.ROTATE_BY_SEND_DAY || '').trim().toLowerCase() === 'yes';

const startupByName = {};
for (const s of $('Read STARTUPS').all()) { startupByName[String(s.json.startup).trim()] = s.json; }
const investorByName = {};
for (const v of $('Read INVESTORS').all()) { investorByName[String(v.json.investor).trim()] = v.json; }

const blank = (x) => x === undefined || x === null || String(x).trim() === '';
const isYes = (x) => String(x).trim().toLowerCase() === 'yes';
const num = (x) => { const n = parseFloat(String(x).replace(/[^0-9.\-]/g, '')); return isNaN(n) ? 0 : n; };
const isoRe = /^\d{4}-\d{2}-\d{2}$/;
const parseDue = (x) => {
  if (blank(x)) return { ok: true, val: null };
  const str = String(x).trim();
  if (!isoRe.test(str)) return { ok: false, val: null };
  const d = DateTime.fromISO(str, { zone: tz });
  if (!d.isValid) return { ok: false, val: null };
  return { ok: true, val: str };
};
const due = (val) => val !== null && val <= today;

const pipeRows = $('Read PIPELINE').all().map(i => i.json);

// ---- Q1: pause column ----
const pauseValues = {};
let pauseNonBlank = 0;
for (const r of pipeRows) {
  if (!blank(r.pause)) { pauseNonBlank++; const v = String(r.pause).trim(); pauseValues[v] = (pauseValues[v]||0)+1; }
}

// ---- Q2: STARTUPS active column ----
const activeValues = {};
let activeYes = 0;
for (const s of $('Read STARTUPS').all()) {
  const v = String(s.json.active == null ? '' : s.json.active).trim();
  activeValues[v || '(blank)'] = (activeValues[v || '(blank)']||0)+1;
  if (isYes(s.json.active)) activeYes++;
}

// ---- deal_shared distribution (Aditya-owned rows) ----
const dealSharedValues = {};
for (const r of pipeRows) {
  if (String(r.owner||'').trim() !== OWNER) continue;
  const v = String(r.deal_shared == null ? '' : r.deal_shared).trim();
  dealSharedValues[v || '(blank)'] = (dealSharedValues[v || '(blank)']||0)+1;
}

// ---- Full decision replay (EXACT fixed logic) ----
const decide = (r) => {
  const ownerVal = String(r.owner || '').trim();
  if (ownerVal === '' || VALID_OWNERS.indexOf(ownerVal) === -1) return { action:'error', reason:'OWNER_INVALID', stage:'' };
  if (ownerVal !== OWNER) return { action:'skip', reason:'not-my-owner', stage:'' };
  if (!blank(r.pause)) return { action:'skip', reason:'row-paused', stage:'' };
  if (!blank(r.investor_response)) return { action:'skip', reason:'investor_response-set', stage:'' };
  if (!blank(r.deal_status) && String(r.deal_status).trim().toLowerCase() !== 'open') return { action:'skip', reason:'deal_status-not-open', stage:'' };
  if (isYes(r.meeting_scheduled) || !blank(r.meeting_date) || num(r.meetings_held) > 0 || !blank(r.last_meeting_date) || !blank(r.meeting_outcome) || num(r.committed_cr) > 0) return { action:'skip', reason:'meeting-stage', stage:'' };
  const inv = investorByName[String(r.investor).trim()];
  if (!inv) return { action:'error', reason:'investor-not-found', stage:'' };
  if (isYes(inv.do_not_contact)) return { action:'skip', reason:'do-not-contact', stage:'' };
  const st = startupByName[String(r.startup).trim()];
  if (!st) return { action:'error', reason:'startup-not-found', stage:'' };
  if (!isYes(st.active)) return { action:'error', reason:'startup-not-active', stage:'' };
  if (blank(r.email)) return { action:'error', reason:'email-missing', stage:'' };
  const varsMissing = blank(st.highlight_1) || blank(st.highlight_2) || blank(st.highlight_3) || blank(st.deck_link) || blank(st.sector) || blank(st.raise_inr_cr) || blank(inv.contact_person) || blank(inv.investor) || blank(st.memo_html);
  if (varsMissing) return { action:'error', reason:'template-var-missing', stage:'' };
  if (!isYes(r.deal_shared)) {
    if (rotateBySendDay && String(st.send_day).trim().toLowerCase() !== todayWeekday.toLowerCase()) return { action:'skip', reason:'rotation-not-today', stage:'' };
    return { action:'send', reason:'initial', stage:'INITIAL' };
  }
  const pd = parseDue(r.next_due);
  if (!pd.ok) return { action:'error', reason:'DATE_PARSE_FAILED', stage:'' };
  if (isYes(r.deal_shared) && !isYes(r.fu3_done) && !pd.val) return { action:'error', reason:'NEXT_DUE_MISSING', stage:'' };
  if (!isYes(r.fu1_done) && due(pd.val)) return { action:'send', reason:'fu1', stage:'FU1' };
  if (!isYes(r.fu2_done) && due(pd.val)) return { action:'send', reason:'fu2', stage:'FU2' };
  if (!isYes(r.fu3_done) && due(pd.val)) return { action:'send', reason:'fu3', stage:'FU3' };
  if (isYes(r.fu3_done)) return { action:'skip', reason:'fu3-complete', stage:'' };
  return { action:'skip', reason:'nothing-due', stage:'' };
};

const actionTally = {};
const stageTally = {};
const sendDeals = [];
for (const r of pipeRows) {
  const d = decide(r);
  actionTally[d.action] = (actionTally[d.action]||0)+1;
  if (d.action === 'send') {
    stageTally[d.stage] = (stageTally[d.stage]||0)+1;
    sendDeals.push({ deal_id: r.deal_id, stage: d.stage, investor: r.investor, email: r.email, deal_shared: r.deal_shared, next_due: r.next_due });
  }
}

// ---- Cap simulation (exactly as Apply daily caps) ----
const totalCap = parseInt(cfg.DAILY_TOTAL_CAP, 10) || 50;
const newCap = parseInt(cfg.DAILY_NEW_SENDS, 10) || 25;
let sentToday = 0;
for (const r of pipeRows) { if (String(r.owner).trim() === OWNER && String(r.last_contact).trim() === today) sentToday++; }
const followups = sendDeals.filter(s => s.stage !== 'INITIAL');
const initials = sendDeals.filter(s => s.stage === 'INITIAL');
let totalRemaining = Math.max(0, totalCap - sentToday);
let wouldSend = 0;
for (const f of followups) { if (totalRemaining<=0) break; wouldSend++; totalRemaining--; }
let newRemaining = newCap;
for (const n of initials) { if (totalRemaining<=0||newRemaining<=0) break; wouldSend++; totalRemaining--; newRemaining--; }

return [{ json: {
  today,
  pipeline_rows_read: pipeRows.length,
  Q1_pause_nonblank_count: pauseNonBlank,
  Q1_pause_distinct_values: pauseValues,
  Q2_startups_active_yes_count: activeYes,
  Q2_startups_active_distinct_values: activeValues,
  aditya_deal_shared_distribution: dealSharedValues,
  decision_action_tally: actionTally,
  decision_send_stage_tally: stageTally,
  total_rows_the_engine_would_SEND_before_caps: sendDeals.length,
  emails_that_WOULD_ACTUALLY_FIRE_this_run_after_caps: wouldSend,
  cap_DAILY_NEW_SENDS: newCap,
  cap_DAILY_TOTAL_CAP: totalCap,
  already_sent_today: sentToday,
  first_20_send_candidates: sendDeals.slice(0,20),
} }];
